-- IPA SG official past questions: 2016 autumn morning, questions 21-30.
-- Questions/options are from the published IPA paper; answers checked against the official key.
-- Official question PDF: https://www.ipa.go.jp/shiken/mondai-kaiotu/gmcbt8000000g6fw-att/2016h28a_sg_am_qs.pdf
-- Official answer key: https://www.ipa.go.jp/shiken/mondai-kaiotu/gmcbt8000000g6fw-att/2016h28a_sg_am_ans.pdf
INSERT OR IGNORE INTO questions
(id,track_id,topic,difficulty,question_type,prompt,options_json,answer_json,explanation,source_type,source_reference,language)
VALUES
('sg-official-h28a-2016-q21','exam-sg','情報セキュリティ特性・完全性','standard','single_choice','【2016年度 平成28年秋期 午前 問21】情報の完全性を脅かす攻撃はどれか。','[{"id":"a","text":"Webページの改ざん"},{"id":"b","text":"システム内に保管されているデータの不正コピー"},{"id":"c","text":"システムを過負荷状態にするDoS攻撃"},{"id":"d","text":"通信内容の盗聴"}]','"a"','正解はア。完全性は情報が正確で改ざんされていない性質であり，Webページの改ざんは完全性を脅かす。','official','https://www.ipa.go.jp/shiken/mondai-kaiotu/gmcbt8000000g6fw-att/2016h28a_sg_am_qs.pdf','ja'),
('sg-official-h28a-2016-q22','exam-sg','Web攻撃・XSS','standard','single_choice','【2016年度 平成28年秋期 午前 問22】クロスサイトスクリプティング（XSS）の手口はどれか。','[{"id":"a","text":"Webアプリケーションの入力フィールドに，悪意のあるJavaScriptコードを含むデータを入力する。"},{"id":"b","text":"ネットワーク経由でサーバに不正アクセスし，データを改ざん又は破壊する。"},{"id":"c","text":"大量のデータをWebアプリケーションに送信し，バッファ領域をあふれさせる。"},{"id":"d","text":"パス名を推定し，認証後にしかアクセスできないページへ直接ジャンプする。"}]','"a"','正解はア。XSSはWebページに悪意のあるスクリプトを混入させ，閲覧者のブラウザ上で実行させる攻撃である。','official','https://www.ipa.go.jp/shiken/mondai-kaiotu/gmcbt8000000g6fw-att/2016h28a_sg_am_qs.pdf','ja'),
('sg-official-h28a-2016-q23','exam-sg','サイバーセキュリティ戦略','standard','single_choice','【2016年度 平成28年秋期 午前 問23】2015年に定められたサイバーセキュリティ戦略の基本原則に含まれるものはどれか。','[{"id":"a","text":"サイバー空間が一部の主体に占有されず，参加を求める者に開かれたものであること。"},{"id":"b","text":"サイバー空間上の脅威への対処は国家が全て代替すること。"},{"id":"c","text":"安全確保のため，サイバー空間で発信された情報を全て検閲すること。"},{"id":"d","text":"情報の自由な流通を尊重し，法令を含むルールや規範を適用しないこと。"}]','"a"','正解はア。サイバー空間の開放性を保ち，多様な主体が参加できることは基本原則の一つである。','official','https://www.ipa.go.jp/shiken/mondai-kaiotu/gmcbt8000000g6fw-att/2016h28a_sg_am_qs.pdf','ja'),
('sg-official-h28a-2016-q24','exam-sg','攻撃者分類・スクリプトキディ','standard','single_choice','【2016年度 平成28年秋期 午前 問24】スクリプトキディの典型的な行為に該当するものはどれか。','[{"id":"a","text":"利用者のIDとパスワード入力を後ろから盗み見する。"},{"id":"b","text":"新しい攻撃手法を考え出す技術はないが，公開された方法に従って不正アクセスを行う。"},{"id":"c","text":"管理者になりすまして電話し，パスワード再発行を依頼する台本を作る。"},{"id":"d","text":"スクリプト言語でプログラムを作成し，迷惑メールを不特定多数に送信する。"}]','"b"','正解はイ。スクリプトキディは，自ら高度な攻撃手法を開発せず，公開済みのツールや手順を利用して攻撃する者を指す。','official','https://www.ipa.go.jp/shiken/mondai-kaiotu/gmcbt8000000g6fw-att/2016h28a_sg_am_qs.pdf','ja'),
('sg-official-h28a-2016-q25','exam-sg','ソーシャルエンジニアリング','standard','single_choice','【2016年度 平成28年秋期 午前 問25】緊急事態を装って組織内部の人からパスワードや機密情報を入手する不正な行為はどれか。','[{"id":"a","text":"ソーシャルエンジニアリング"},{"id":"b","text":"踏み台攻撃"},{"id":"c","text":"トロイの木馬"},{"id":"d","text":"ブルートフォース攻撃"}]','"a"','正解はア。緊急事態などを装って人の心理を利用し，秘密情報を聞き出す行為はソーシャルエンジニアリングである。','official','https://www.ipa.go.jp/shiken/mondai-kaiotu/gmcbt8000000g6fw-att/2016h28a_sg_am_qs.pdf','ja'),
('sg-official-h28a-2016-q26','exam-sg','パスワード攻撃・パスワードリスト攻撃','standard','single_choice','【2016年度 平成28年秋期 午前 問26】パスワードリスト攻撃に該当するものはどれか。','[{"id":"a","text":"一般的な単語や人名からパスワードのリストを作り，ログインを試みる。"},{"id":"b","text":"想定されるパスワードとハッシュ値の対を使い，入手したハッシュ値からパスワードを解析する。"},{"id":"c","text":"別のWebサイトから流出した利用者IDとパスワードのリストを使い，他のWebサイトへのログインを試みる。"},{"id":"d","text":"画面上の入力操作を録画して，その記録を使って端末へのログインを試みる。"}]','"c"','正解はウ。パスワードリスト攻撃は，他サービスから流出したID・パスワードの組合せを別サービスで試す攻撃である。','official','https://www.ipa.go.jp/shiken/mondai-kaiotu/gmcbt8000000g6fw-att/2016h28a_sg_am_qs.pdf','ja'),
('sg-official-h28a-2016-q27','exam-sg','マルウェア・ランサムウェア','standard','single_choice','【2016年度 平成28年秋期 午前 問27】ランサムウェアに分類されるものはどれか。','[{"id":"a","text":"感染端末から外部へ通信できるようにし，遠隔操作を可能にするマルウェア"},{"id":"b","text":"感染端末に保存されたパスワード情報を盗み出すマルウェア"},{"id":"c","text":"キー操作を記録し，ネットバンキングの暗証番号を盗むマルウェア"},{"id":"d","text":"感染端末のファイルを暗号化し，復号と引換えに金銭を要求するマルウェア"}]','"d"','正解はエ。ランサムウェアはデータを暗号化するなどして利用できなくし，復旧と引換えに金銭を要求する。','official','https://www.ipa.go.jp/shiken/mondai-kaiotu/gmcbt8000000g6fw-att/2016h28a_sg_am_qs.pdf','ja'),
('sg-official-h28a-2016-q28','exam-sg','メールセキュリティ・電子署名','standard','single_choice','【2016年度 平成28年秋期 午前 問28】なりすましメールではなく，ECサイトから届いたものであることを確認するうえで適切なものはどれか。','[{"id":"a","text":"送信元メールアドレスがECサイトで利用されているアドレスである。"},{"id":"b","text":"送信元メールアドレスのドメインがECサイトのものである。"},{"id":"c","text":"ディジタル署名の署名者メールアドレスのドメインがECサイトのものである。"},{"id":"d","text":"メール本文末尾のテキスト署名に記載された組織名がECサイトのものである。"}]','"c"','正解はウ。単に送信元アドレスや本文に記載された情報を見るだけでは偽装できるため，電子署名を検証することが重要である。','official','https://www.ipa.go.jp/shiken/mondai-kaiotu/gmcbt8000000g6fw-att/2016h28a_sg_am_qs.pdf','ja'),
('sg-official-h28a-2016-q29','exam-sg','PKI・認証局','standard','single_choice','【2016年度 平成28年秋期 午前 問29】PKI（公開鍵基盤）における認証局が果たす役割はどれか。','[{"id":"a","text":"共通鍵を生成する。"},{"id":"b","text":"公開鍵を利用してデータを暗号化する。"},{"id":"c","text":"失効したディジタル証明書の一覧を発行する。"},{"id":"d","text":"データが改ざんされていないことを直接検証する。"}]','"c"','正解はウ。認証局は証明書の発行・管理を行い，失効した証明書の情報をCRL等で公開する。','official','https://www.ipa.go.jp/shiken/mondai-kaiotu/gmcbt8000000g6fw-att/2016h28a_sg_am_qs.pdf','ja'),
('sg-official-h28a-2016-q30','exam-sg','セキュリティ評価・Common Criteria','standard','single_choice','【2016年度 平成28年秋期 午前 問30】情報技術セキュリティ評価のための国際標準であり，コモンクライテリア（CC）と呼ばれるものはどれか。','[{"id":"a","text":"ISO 9001"},{"id":"b","text":"ISO 14004"},{"id":"c","text":"ISO/IEC 15408"},{"id":"d","text":"ISO/IEC 27005"}]','"c"','正解はウ。Common Criteria（CC）はIT製品・システムのセキュリティ機能を評価する国際標準ISO/IEC 15408である。','official','https://www.ipa.go.jp/shiken/mondai-kaiotu/gmcbt8000000g6fw-att/2016h28a_sg_am_qs.pdf','ja');
